--
-- Struktur dari tabel `surat`
--

CREATE TABLE `surat` (
  `id` int(11) UNSIGNED NOT NULL,
  `public_id` varchar(36) NOT NULL,
  `user_id` int(11) UNSIGNED NOT NULL,
  `proker_id` int(11) UNSIGNED DEFAULT NULL,
  `kategori_id` int(11) UNSIGNED DEFAULT NULL,
  `jenis_surat` enum('non_elektronik','elektronik') DEFAULT 'non_elektronik',
  `nomor_surat` varchar(100) DEFAULT NULL,
  `lampiran` varchar(50) DEFAULT NULL,
  `perihal` varchar(255) NOT NULL,
  `ttd_ketua_bem` varchar(64) DEFAULT NULL,
  `ttd_dekan` varchar(64) DEFAULT NULL,
  `tujuan_surat` varchar(255) DEFAULT NULL,
  `tempat_tujuan` varchar(100) DEFAULT NULL,
  `isi_paragraf` text DEFAULT NULL,
  `paragraf_isi` text DEFAULT NULL,
  `tanggal_kegiatan_mulai` date DEFAULT NULL,
  `tanggal_kegiatan_selesai` date DEFAULT NULL,
  `waktu_kegiatan_mulai` time DEFAULT NULL,
  `waktu_kegiatan_selesai` varchar(20) DEFAULT NULL,
  `tempat_kegiatan` varchar(255) DEFAULT NULL,
  `penutup_paragraf` text DEFAULT NULL,
  `isi_lampiran` longtext DEFAULT NULL,
  `status` enum('Draft','Pending','Approved','Rejected') NOT NULL DEFAULT 'Draft',
  `catatan_revisi` text DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

