INSERT INTO `surat` (`id`, `public_id`, `user_id`, `proker_id`, `kategori_id`, `jenis_surat`, `nomor_surat`, `lampiran`, `perihal`, `ttd_ketua_bem`, `ttd_dekan`, `tujuan_surat`, `tempat_tujuan`, `isi_paragraf`, `paragraf_isi`, `tanggal_kegiatan_mulai`, `tanggal_kegiatan_selesai`, `waktu_kegiatan_mulai`, `waktu_kegiatan_selesai`, `tempat_kegiatan`, `penutup_paragraf`, `isi_lampiran`, `status`, `catatan_revisi`, `created_at`, `updated_at`) VALUES
(5, 'd15cca66-8acf-4dca-a305-363fc1c9972c', 29, 4, NULL, 'non_elektronik', 'ISTIMEWA', '', 'Permohonan Pengajuan Dana', NULL, NULL, 'Dekan Fakultas Ilmu Komputer\r\nUniversitas Singaperbangsa Karawang', 'Tempat', 'Teriring salam dan doa, semoga Allah SWT senantiasa memberikan kesejahteraan dan rahmat-Nya kepada kita dalam menjalankan segala aktivitas sehari-hari. Aamiin.', NULL, '2026-04-03', '2026-04-04', '00:00:00', 'Selesai', 'Batalyon Artileri Medan 9/Kostrad Purwakarta', 'Maka dengan ini kami panitia pelaksana LKMM 2025, bermaksud menyampaikan Permohonan Pengajuan Dana sebesar Rp. 9.092.000. (Sembilan Juta Sembilan Puluh Dua Ribu Rupiah).\r\nDemikian surat permohonan pengajuan ini kami sampaikan, atas perhatian dan kerjasamanya kami ucapkan terima kasih.', '{\"sembunyikan_tabel\":false,\"pages\":[]}', 'Approved', NULL, '2026-04-03 16:27:12', '2026-04-05 19:16:31');
INSERT INTO `surat` (`id`, `public_id`, `user_id`, `proker_id`, `kategori_id`, `jenis_surat`, `nomor_surat`, `lampiran`, `perihal`, `ttd_ketua_bem`, `ttd_dekan`, `tujuan_surat`, `tempat_tujuan`, `isi_paragraf`, `paragraf_isi`, `tanggal_kegiatan_mulai`, `tanggal_kegiatan_selesai`, `waktu_kegiatan_mulai`, `waktu_kegiatan_selesai`, `tempat_kegiatan`, `penutup_paragraf`, `isi_lampiran`, `status`, `catatan_revisi`, `created_at`, `updated_at`) VALUES
(6, 'dd65426c-e7c3-4ee8-9dac-174aecef7e35', 29, 4, NULL, 'non_elektronik', '001/TPA-MIC/BEM-FASILKOM/IV/2026', '', 'Undangan Sosialisasi', 'Ketua BEM Fasilkom', NULL, 'Koordinator Kelas Sistem Informasi Angkatan 2025\r\nFakultas Ilmu Komputer\r\nUniversitas Singaperbangsa Karawang', 'Tempat', 'Teriring salam dan doa, semoga Allah SWT senantiasa memberikan kesejahteraan dan rahmat-Nya kepada kita dalam menjalankan segala aktivitas sehari-hari. Aamiin.', 'Sehubungan akan dilaksanakannya kegiatan Sosialisasi Latihan Keterampilan Manajemen Mahasiswa (LKMM) 2025 dengan tema “Lead with Purpose, Action with Integrity” yang akan dilaksanakan pada:', '2026-04-06', '2026-04-06', '02:00:00', 'Selesai', 'Zoom Meeting (Link Menyusul)', 'Maka dengan ini kami panitia pelaksana LKMM 2025, bermaksud mengundang Koordinator Kelas Program Studi Sistem Informasi Angkatan 2025 Fakultas Ilmu Komputer untuk hadir dalam Sosialisasi Acara LKMM 2025. \r\nDemikian surat pemberitahuan kegiatan mahasiswa ini kami sampaikan, atas perhatian dan kerjasamanya kami ucapkan terima kasih.', '{\"sembunyikan_tabel\":false,\"pages\":[\"<p class=\\\"Normal1\\\" style=\\\"margin-bottom: 0cm; text-align: center; line-height: 150%;\\\" align=\\\"center\\\"><strong style=\\\"mso-bidi-font-weight: normal;\\\"><span lang=\\\"EN-US\\\" style=\\\"font-size: 12.0pt; line-height: 150%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; color: windowtext;\\\">SUSUNAN ACARA<\\/span><\\/strong><\\/p>\\r\\n<p class=\\\"Normal1\\\" style=\\\"margin-bottom: 0cm; text-align: center; line-height: 150%;\\\" align=\\\"center\\\"><strong><span lang=\\\"IN\\\" style=\\\"font-size: 12.0pt; line-height: 150%; font-family: \'Times New Roman\',serif; mso-ansi-language: IN; mso-fareast-language: ZH-CN; mso-bidi-font-style: italic;\\\">LATIHAN KETERAMPILAN MANAJEMEN MAHASISWA<\\/span><\\/strong><\\/p>\\r\\n<p class=\\\"Normal1\\\" style=\\\"margin-bottom: 0cm; text-align: center; line-height: 150%;\\\" align=\\\"center\\\"><strong><span lang=\\\"IN\\\" style=\\\"font-size: 12.0pt; line-height: 150%; font-family: \'Times New Roman\',serif; mso-ansi-language: IN; mso-fareast-language: ZH-CN; mso-bidi-font-style: italic;\\\">(LKMM) 2025<\\/span><\\/strong><\\/p>\\r\\n<p class=\\\"Normal1\\\" style=\\\"margin-bottom: 0cm; text-align: center; line-height: 150%;\\\" align=\\\"center\\\"><strong style=\\\"mso-bidi-font-weight: normal;\\\"><span lang=\\\"EN-US\\\" style=\\\"font-size: 12.0pt; line-height: 150%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; color: windowtext;\\\">BADAN EKSEKUTIF MAHASISWA<\\/span><\\/strong><\\/p>\\r\\n<p class=\\\"Normal1\\\" style=\\\"margin-bottom: 0cm; text-align: center; line-height: 150%;\\\" align=\\\"center\\\"><strong style=\\\"mso-bidi-font-weight: normal;\\\"><span lang=\\\"EN-US\\\" style=\\\"font-size: 12.0pt; line-height: 150%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; color: windowtext;\\\">FAKULTAS ILMU KOMPUTER<\\/span><\\/strong><\\/p>\\r\\n<p class=\\\"Normal1\\\" style=\\\"margin-bottom: 0cm; text-align: center; line-height: 150%;\\\" align=\\\"center\\\"><strong style=\\\"mso-bidi-font-weight: normal;\\\"><span lang=\\\"EN-US\\\" style=\\\"font-size: 12.0pt; line-height: 150%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; color: windowtext;\\\">UNIVERSITAS SINGAPERBANGSA KARAWANG<\\/span><\\/strong><\\/p>\\r\\n<p class=\\\"Normal1\\\" style=\\\"margin-bottom: 0cm; line-height: 150%; text-align: left;\\\" align=\\\"center\\\">&nbsp;<\\/p>\\r\\n<p class=\\\"Normal1\\\" style=\\\"margin-bottom: 0cm; line-height: 150%;\\\"><strong style=\\\"mso-bidi-font-weight: normal;\\\"><span lang=\\\"IN\\\" style=\\\"font-size: 12.0pt; line-height: 150%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; color: windowtext; mso-ansi-language: IN;\\\">Sabtu, 13 September 2025<