INSERT INTO `surat` (`id`, `public_id`, `user_id`, `proker_id`, `kategori_id`, `jenis_surat`, `nomor_surat`, `lampiran`, `perihal`, `ttd_ketua_bem`, `ttd_dekan`, `tujuan_surat`, `tempat_tujuan`, `isi_paragraf`, `paragraf_isi`, `tanggal_kegiatan_mulai`, `tanggal_kegiatan_selesai`, `waktu_kegiatan_mulai`, `waktu_kegiatan_selesai`, `tempat_kegiatan`, `penutup_paragraf`, `isi_lampiran`, `status`, `catatan_revisi`, `created_at`, `updated_at`) VALUES
(12, '783406aa-7229-4778-a98b-61a04afdb3d6', 29, 4, NULL, 'elektronik', '004/TPA-MIC/BEM-FASILKOM/IV/2026', '1', 'tes', NULL, NULL, 'Dekan\r\nFakultas Ilmu Komputer\r\nUniversitas Singaperbangsa Karawang', 'Tempat', 'Teriring salam dan doa, semoga Allah SWT senantiasa memberikan kesejahteraan dan rahmat-Nya kepada kita dalam menjalankan segala aktivitas sehari-hari. Aamiin.', 'Sehubungan akan dilaksanakannya kegiatan [Nama Kegiatan] dengan tema \"[Tema Kegiatan]\" yang akan dilaksanakan pada:', '2026-04-20', '2026-04-20', '22:55:00', 'Selesai', 'Aula Syekh Quro Unsika', 'Maka dengan ini kami Panitia Pelaksana bermaksud menyampaikan Pemberitahuan Kegiatan Mahasiswa terkait pelaksanaan kegiatan tersebut.\r\nDemikian surat pemberitahuan kegiatan mahasiswa ini kami sampaikan, atas perhatian dan kerjasamanya kami ucapkan terima kasih.', '{\"sembunyikan_tabel\":false,\"pages\":[]}', 'Approved', NULL, '2026-04-20 15:55:57', '2026-04-20 19:01:15'),
(13, 'cfd1dc63-ace9-48a7-b72c-91c10668f892', 29, 4, NULL, 'elektronik', '003/TPA-MIC/BEM-FASILKOM/IV/2026', '1 (satu) lembar', 'Permohonan Peminjaman Alat', 'Ketua BEM Fasilkom', NULL, 'Ketua Badan Eksekutif Mahasiswa\r\nFakultas Ilmu Komputer\r\nUniversitas Singaperbangsa Karawang', 'Tempat', '<p>Teriring salam dan doa, semoga Allah SWT senantiasa memberikan kesejahteraan dan rahmat-Nya kepada kita dalam menjalankan segala aktivitas sehari-hari. Aamiin.</p>', '<p><span lang=\"ZH-CN\" style=\"font-size: 12.0pt; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; mso-font-kerning: 0pt; mso-ansi-language: ZH-CN; mso-fareast-language: ZH-CN; mso-bidi-language: AR-SA;\">Sehubungan<span style=\"letter-spacing: .05pt;\"> </span>akan<span style=\"letter-spacing: .05pt;\"> </span>dilaksanakannya<span style=\"letter-spacing: .05pt;\"> </span>kegiatan<span style=\"letter-spacing: .05pt;\"> </span><strong style=\"mso-bidi-font-weight: normal;\"><em>Make It Connect</em><em style=\"mso-bidi-font-style: normal;\"><span style=\"letter-spacing: .05pt;\"> </span></em>202</strong></span><strong style=\"mso-bidi-font-weight: normal;\"><span lang=\"EN-US\" style=\"font-size: 12.0pt; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; mso-font-kerning: 0pt; mso-ansi-language: EN-US; mso-fareast-language: ZH-CN; mso-bidi-language: AR-SA;\">5</span><span lang=\"EN-US\" style=\"font-size: 12.0pt; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; letter-spacing: .05pt; mso-font-kerning: 0pt; mso-ansi-language: ZH-CN; mso-fareast-language: ZH-CN; mso-bidi-language: AR-SA;\"> </span></strong><span lang=\"ZH-CN\" style=\"font-size: 12.0pt; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; mso-font-kerning: 0pt; mso-ansi-language: ZH-CN; mso-fareast-language: ZH-CN; mso-bidi-language: AR-SA;\">dengan<span style=\"letter-spacing: .05pt;\"> </span>tema<span style=\"letter-spacing: .05pt;\"> </span><strong><em>&ldquo;</em></strong><strong style=\"mso-bidi-font-weight: normal;\"><em style=\"mso-bidi-font-style: normal;\">Build the Bridge, Broaden the Impact<span style=\"mso-bidi-font-weight: bold; mso-bidi-font-style: italic;\">&rdquo;</span></em></strong> dengan </span><strong><span lang=\"EN-US\" style=\"font-size: 12.0pt; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; mso-font-kerning: 0pt; mso-ansi-language: EN-US; mso-fareast-language: ZH-CN; mso-bidi-language: AR-SA;\">President University Faculty Association &ndash; Computer Science</span></strong><span lang=\"ZH-CN\" style=\"font-size: 12.0pt; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; mso-font-kerning: 0pt; mso-ansi-language: ZH-CN; mso-fareast-language: ZH-CN; mso-bidi-language: AR-SA;\"> yang akan<span style=\"letter-spacing: .05pt;\"> </span>dilaksanakan<span style=\"letter-spacing: -.05pt;\"> </span>pada:</span></p>', '2026-04-21', '2026-04-21', '00:00:00', 'Selesai', 'Aula Syekh Quro Unsika', '<p class=\"MsoNormal\" style=\"text-align: justify; text-justify: inter-ideograph; text-indent: 36.0pt; line-height: 115%;\"><span lang=\"ZH-CN\">Maka dengan ini, kami Panitia Pelaksana <strong><em>Make It Connect</em> 202</strong></span><strong><span lang=\"EN-US\" style=\"mso-ansi-language: EN-US;\">5</span></strong><span lang=\"ZH-CN\"> bermaksud mengajukan <strong><em>Permohonan Peminjaman Barang (terlampir)</em></strong> demi terlaksananya kegiatan tersebut.</span></p>\r\n<p><span lang=\"ZH-CN\" style=\"font-size: 12.0pt; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; mso-font-kerning: 0pt; mso-ansi-language: ZH-CN; mso-fareast-language: ZH-CN; mso-bidi-language: AR-SA;\">Demikian surat permohonan ini kami sampaikan, atas perhatian dan kerjasamanya kami ucapkan terima kasih.</span></p>', '{\"sembunyikan_tabel\":false,\"pages\":[\"<p style=\\\"te